package dev.shadw.asgard.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Draugr with its own model and texture. Generated by shadw-mod mob. */
public class DraugrRenderer extends MobRenderer<Draugr, DraugrModel.State, DraugrModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/draugr.png");

	public DraugrRenderer(EntityRendererProvider.Context context) {
		super(context, new DraugrModel(context.bakeLayer(DraugrModel.LAYER)), 0.55F);
	}

	@Override
	public DraugrModel.State createRenderState() {
		return new DraugrModel.State();
	}

	@Override
	public void extractRenderState(Draugr entity, DraugrModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(DraugrModel.State state) {
		return TEXTURE;
	}
}
